import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int K = fs.nextInt();
        int C = fs.nextInt();

        long[] pref = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            pref[i] = pref[i - 1] + fs.nextInt();
        }

        long[] dpPrev = new long[N + 1];
        long[] dpCur = new long[N + 1];

        for (int j = 1; j <= K; j++) {
            int start = j * C;

            dpCur[start] = dpPrev[start - C] + pref[start] - pref[start - C];

            for (int i = start + 1; i <= N; i++) {
                long best = dpCur[i - 1];
                long place = dpPrev[i - C] + pref[i] - pref[i - C];

                if (place < best) {
                    best = place;
                }

                dpCur[i] = best;
            }

            long[] temp = dpPrev;
            dpPrev = dpCur;
            dpCur = temp;
        }

        long total = pref[N];
        System.out.println(total - dpPrev[N]);
    }
}
